#!/bin/sh
# GENERATED by generate.py -- shared environment of px4_sim_5ugv_5uav_warehouse_light (5 UGV + UAV
# pairs). Sourced by every pane (session.yml pre_window) and by deploy.sh. POSIX sh.
#
#   pair k: ugv<k> = PX4 instance 2(k-1) (instance 0 hosts the gz world), uav<k> = instance 2(k-1)+1
#   MAV_SYS_ID = instance + 1, uXRCE-DDS namespace ugv_<k> / uav_<k>, onboard MAVLink port 14580 + instance.
# Every vehicle's EKF is relative to its own spawn point: px4_bridge adds home_offset_x/y/z (= the
# spawn) so all of them share the frame "world" (= gz world).

export N_PAIRS=5
export TMUX_SESSION_NAME=ugv_uav_warehouse_5pairs
export TMUX_SOCKET_NAME=whugvuav5p
export ROS_DOMAIN_ID=${UGV_UAV_5PAIRS_DOMAIN_ID:-51}
export PX4_DIR=${PX4_DIR:-$HOME/git/PX4-Autopilot}
export PX4_GZ_WORLD=${PX4_GZ_WORLD:-warehouse_light}
# headless by default here (the gz GUI renders the whole warehouse again): HEADLESS=0 ./start.sh for it
if [ "${HEADLESS:-1}" = "1" ]; then export HEADLESS=1; else unset HEADLESS; fi
export GZ_IP=127.0.0.1
export USE_SIM_TIME=true
export PLANNER=${PLANNER:-global}
export CONTROL_FRAME=world

# Optional CPU split (PIN_CPUS=1): gz alone on GZ_CPUS (`gz` window), every other pane on OTHER_CPUS
# (session.yml pre_window). Off by default: it did not raise the real-time factor on this laptop.
export PIN_CPUS=${PIN_CPUS:-0}
export GZ_CPUS=${GZ_CPUS:-0-3}
export OTHER_CPUS=${OTHER_CPUS:-4-$(($(nproc) - 1))}

export UGV_SPAWN_Z=0.05
export UGV_HOME_Z=0.6
export UAV_SPAWN_Z=0.32
export UAV_HOME_Z=0.56

export UGV1_X=0.0 UGV1_Y=0.0
export UGV2_X=0.0 UGV2_Y=-4.2
export UGV3_X=0.0 UGV3_Y=8.4
export UGV4_X=0.0 UGV4_Y=-12.6
export UGV5_X=-0.7 UGV5_Y=4.2
